import itertools, json
jobs='ABCDE'
slot={'A':[4,8,0,2,0],'B':[6,4,5,0,5],'C':[2,6,4,6,0],'D':[8,7,9,6,0],'E':[3,3,1,6,5]}
mat=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(mat[jobs.index(a)][jobs.index(b)] for a,b in zip(p,p[1:]))
def valid(p,s):
 pos={j:p.index(j)+1 for j in jobs}
 if pos['A']>=pos['D']: return False
 return {'rain':pos['E']!=2 and pos['D']!=5,'road':pos['B']!=5 and pos['D']!=1,'lift':pos['D']!=4 and pos['C']!=1}[s]
def penalty(p,s):
 return {'rain':6*max(0,p.index('A')+1-2),'road':8*max(0,p.index('C')+1-3),'lift':5*max(0,p.index('E'))}[s]
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'): continue
 candidates=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];candidates.append((tuple(q),4))
 best={}
 for s in ['rain','road','lift']:
  options=[(nominal(q)+penalty(q,s)+fee,''.join(q)) for q,fee in candidates if valid(q,s)]
  if not options: break
  best[s]=min(options)
 if len(best)==3:
  results.append((nominal(p)+max(c for c,q in best.values()),''.join(p),best))
results.sort()
best=results[0]
print(json.dumps({'roster':best[1],'score':best[0],'repairs':{s:v[1] for s,v in best[2].items()},'repair_costs':{s:v[0] for s,v in best[2].items()},'feasible_count':len(results),'next_score':min(r[0] for r in results if r[0]>best[0])}))
print('publication nominal',nominal(tuple(best[1])))
print('optima',[(r[0],r[1]) for r in results if r[0]==best[0]])

