import itertools,json
jobs='ABCDE';start='ACEBD'
slot={'A':[4,8,0,2,0],'B':[6,4,5,0,5],'C':[2,6,4,6,0],'D':[8,7,9,6,0],'E':[3,3,1,6,5]}
mat=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
def distance(p):
 perm=[start.index(j) for j in p];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;k=i
   while k not in seen:seen.add(k);k=perm[k]
 return 5-cycles
classes={i:[] for i in range(3)}
for p in itertools.permutations(jobs):
 d=distance(p)
 if d>2:continue
 pos={j:p.index(j)+1 for j in jobs}
 if not(pos['A']<pos['D'] and pos['E'] not in (2,3) and pos['D']!=5):continue
 nominal=sum(slot[j][i] for i,j in enumerate(p))+sum(mat[jobs.index(a)][jobs.index(b)] for a,b in zip(p,p[1:]))
 cost=nominal+6*max(0,pos['A']-2)+4*d+(5 if d==2 else 0)
 classes[d].append((cost,''.join(p)))
best=min(v for vs in classes.values() for v in vs)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(vs)[0] if vs else None for d,vs in classes.items()},'feasible_by_swaps':{str(d):len(vs) for d,vs in classes.items()}}))
print(classes)

